enum EPanelScreenCommand {
  /** 创建屏幕 */
  screenCreate = 100,
  /** 选中屏幕 */
  screenSelect,
  /** 激活屏幕 */
  screenActive,
  /** 取消选中屏幕 */
  screenUnselect,
  /** 删除单个屏幕 */
  screenDelete,
  /** 批量删除屏幕 */
  screenDeleteMuti,
  /** 以下都是 上位机自定义指令枚举删除空屏幕，彪哥加的用来处理空屏幕的删除动作 */
  screenDeleteEmpty = 999,
}
